                new PointNRound(new Offset(0.500, 0.268), new CornerRounding(0.016)),
                new PointNRound(new Offset(0.792, -0.066), new CornerRounding(0.958)),
                new PointNRound(new Offset(1.064, 0.276), new CornerRounding(1.000)),
