function arch(): RoundedPolygon {
  return rotatePolygon(
    createPolygonFromVertices(
      // 4 vertices for a square, manually positioning
      (() => {
        const r = 1;
        const verts: number[] = [];
        for (let i = 0; i < 4; i++) {
          const angle = (floatPi / 4) * 2 * i;
          verts.push(Math.cos(angle) * r, Math.sin(angle) * r);
        }
        return verts;
      })(),
      unrounded,
      [r100, r100, r20, r20],
      0,
      0
    ),
    -135
  );
